        <label ng-model="$ctrl.enfermeria.vac_fiebre_amarilla" btn-checkbox-false="0" btn-checkbox-true="1" uib-btn-checkbox ng-click="$ctrl.guardarValorEnfermeria($ctrl.enfermeria, 'vac_fiebre_amarilla', $ctrl.enfermeria.vac_fiebre_amarilla)" class="btn btn-primary">Fiebre amarilla</label>
